	'messages:apihelp-query+random-param-filterredir' => 'ia:Como filtrar pro monstrar redirectiones.',
	'messages:apihelp-query+random-example-simple' => 'ia:Restituer duo paginas aleatori del spatio de nomines principal.',
	'messages:apihelp-query+random-example-generator' => 'ia:Restituer information de pagina sur duo paginas aleatori del spatio de nomines principal.',
	'messages:apihelp-query+random-example-minsize' => 'ia:Restitue information sur un pagina aleatori del spatio de nomines principal que contine al minus 500 bytes de texto.',
	'messages:apihelp-query+recentchanges-summary' => 'ia:Enumerar le modificationes recente.',
