	'messages:apihelp-query+recentchanges-paramvalue-prop-ids' => 'ia:Adde le ID de pagina, le ID de modificationes recente e le IDs del versiones nove e ancian.',
	'messages:apihelp-query+recentchanges-paramvalue-prop-sizes' => 'ia:Adde le longitude nove e ancian del pagina in bytes.',
	'messages:apihelp-query+recentchanges-paramvalue-prop-redirect' => 'ia:Marca le modification con un etiquetta si le pagina es un redirection.',
