	'messages:config-admin-password-mismatch' => 'ia:Le duo contrasignos que tu scribeva non es identic.',
	'messages:config-admin-email' => 'ia:Adresse de e-mail:',
	'messages:config-admin-email-help' => 'ia:Entra un adresse de e-mail hic pro permitter le reception de e-mail ab altere usatores del wiki, pro poter reinitialisar tu contrasigno, e pro reciper notification de cambios a paginas in tu observatorio. Iste campo pote esser lassate vacue.',
	'messages:config-admin-error-user' => 'ia:Error interne durante le creation de un administrator con le nomine "<nowiki>$1</nowiki>".',
	'messages:config-admin-error-password' => 'ia:Error interne durante le definition de un contrasigno pro le administrator "<nowiki>$1</nowiki>": <pre>$2</pre>',
	'messages:config-admin-error-password-invalid' => 'ia:Contrasigno de administrator invalide: $1',
